#include <vector>
#include <cstddef>
#include <cmath>
#include <algorithm>
#include <omp.h>

struct COOElement {
    size_t row, column;
    double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Use OpenMP to compute in parallel.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    const double EPS = 1e-12;

    x.assign(N, 0.0);
    if (b.size() < N || N == 0) return;

    // Build a dense augmented matrix [A | b].
    // Parallel-safe because each row is written by exactly one thread in the initialization loop,
    // and COO accumulation uses atomic updates.
    std::vector<double> aug(N * (N + 1), 0.0);

    #pragma omp parallel for schedule(static)
    for (size_t i = 0; i < N; ++i) {
        aug[i * (N + 1) + N] = b[i];
    }

    #pragma omp parallel for schedule(static)
    for (size_t k = 0; k < A.size(); ++k) {
        const COOElement &e = A[k];
        if (e.row < N && e.column < N) {
            #pragma omp atomic update
            aug[e.row * (N + 1) + e.column] += e.value;
        }
    }

    // Gaussian elimination with partial pivoting.
    // The pivot search uses a reduction-safe manual pattern with per-thread local bests,
    // then a critical section to combine them.
    for (size_t col = 0; col < N; ++col) {
        size_t pivot_row = col;
        double pivot_abs = std::fabs(aug[col * (N + 1) + col]);

        #pragma omp parallel
        {
            size_t local_row = col;
            double local_abs = pivot_abs;

            #pragma omp for nowait
            for (size_t r = col; r < N; ++r) {
                double v = std::fabs(aug[r * (N + 1) + col]);
                if (v > local_abs) {
                    local_abs = v;
                    local_row = r;
                }
            }

            #pragma omp critical
            {
                if (local_abs > pivot_abs) {
                    pivot_abs = local_abs;
                    pivot_row = local_row;
                }
            }
        }

        if (pivot_abs < EPS) {
            // Singular or rank-deficient system: leave unresolved variables as 0 where needed.
            continue;
        }

        if (pivot_row != col) {
            #pragma omp parallel for schedule(static)
            for (size_t j = col; j <= N; ++j) {
                std::swap(aug[col * (N + 1) + j], aug[pivot_row * (N + 1) + j]);
            }
        }

        const double diag = aug[col * (N + 1) + col];

        // Eliminate rows below the pivot.
        #pragma omp parallel for schedule(static)
        for (size_t r = col + 1; r < N; ++r) {
            double factor = 0.0;
            if (std::fabs(diag) >= EPS) {
                factor = aug[r * (N + 1) + col] / diag;
            }
            aug[r * (N + 1) + col] = 0.0;
            for (size_t j = col + 1; j <= N; ++j) {
                aug[r * (N + 1) + j] -= factor * aug[col * (N + 1) + j];
            }
        }
    }

    // Back substitution (sequential due to dependency chain).
    for (size_t i_rev = 0; i_rev < N; ++i_rev) {
        size_t i = N - 1 - i_rev;
        double rhs = aug[i * (N + 1) + N];

        double sum = 0.0;
        #pragma omp parallel for reduction(+:sum) schedule(static)
        for (size_t j = i + 1; j < N; ++j) {
            sum += aug[i * (N + 1) + j] * x[j];
        }

        double diag = aug[i * (N + 1) + i];
        if (std::fabs(diag) >= EPS) {
            x[i] = (rhs - sum) / diag;
        } else {
            // Free or inconsistent variable; choose 0 for stability.
            x[i] = 0.0;
        }
    }
}
